import { Box, Button, Grid, IconButton, Typography } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import PointOfSaleIcon from '@mui/icons-material/PointOfSale';
import React, { useState } from 'react';
import Customer from './Customer';
import { appColors, HEADER_GRADIENT } from '../../../../theme/appColors';
import Summary from './Summary';
import BasketItems from './BasketItems';
import PaymentMethodsModel from '../SalesRight/Model/PaymentMethodsModel';
import { PaymentType } from '../../../../core/types/commonType';
import { useAppSelector } from '../../../../store/hooks';
import { selectBasketItems } from '../../store/SalesRichBasketSelector';

interface Props {
  cartOpen: boolean;
  isTablet: boolean;
  onClose: () => void;
}

const colHeader = (label: string, align: 'left' | 'right' = 'right') => (
  <Typography
    align={align}
    sx={{
      textTransform: 'uppercase',
      fontWeight: 700,
      fontSize: 10,
      color: 'rgba(255,255,255,0.8)',
      letterSpacing: '0.5px',
    }}
  >
    {label}
  </Typography>
);

const Index = ({ cartOpen, isTablet, onClose }: Props) => {
  const [openPayment, setOpenPayment] = useState(false);
  const basketItems = useAppSelector(selectBasketItems);
  const hasItems = basketItems.length > 0;

  return (
    <>
      {/* Backdrop — tablet only */}
      {isTablet && (
        <Box
          onClick={onClose}
          sx={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0,0,0,0.45)',
            zIndex: 19,
            opacity: cartOpen ? 1 : 0,
            pointerEvents: cartOpen ? 'auto' : 'none',
            transition: 'opacity 0.28s ease',
          }}
        />
      )}

      <Box
        sx={{
          position: 'fixed',
          display: 'flex',
          flexDirection: 'column',
          zIndex: 20,
          overflow: 'hidden',
          backgroundColor: appColors.white,
          boxShadow: '0 4px 24px rgba(0,20,137,0.14)',

          /* ── Desktop ── */
          left: { md: 4 },
          width: { md: '38%', lg: '32%', xl: '30%' },
          height: { md: 'calc(100vh - 72px)', lg: 'calc(100vh - 96px)' },
          borderRadius: { md: '12px' },

          /* ── Tablet: full-height slide-in from right ── */
          ...(isTablet && {
            left: 'auto',
            right: 0,
            top: 0,
            height: '100dvh',
            width: 'min(88vw, 400px)',
            borderRadius: '12px 0 0 12px',
            transform: cartOpen ? 'translateX(0)' : 'translateX(100%)',
            transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
          }),
        }}
      >
        {/* Tablet header with close button */}
        {isTablet && (
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              px: 2,
              py: 1,
              background: HEADER_GRADIENT,
            }}
          >
            <Typography sx={{ fontWeight: 700, fontSize: '0.95rem', color: '#fff' }}>
              Cart
            </Typography>
            <IconButton
              onClick={onClose}
              size="small"
              sx={{ color: 'rgba(255,255,255,0.85)' }}
            >
              <CloseIcon fontSize="small" />
            </IconButton>
          </Box>
        )}

        {/* Customer & product search */}
        <Box
          sx={{
            p: '10px 10px 8px 10px',
            backgroundColor: appColors.white,
            borderBottom: `1px solid ${appColors.darkGray[10]}`,
          }}
        >
          <Customer />
        </Box>

        {/* Column headers */}
        <Box
          sx={{
            background: HEADER_GRADIENT,
            px: '12px',
            py: '8px',
          }}
        >
          <Grid
            container
            flexWrap="nowrap"
            spacing={1}
          >
            <Grid
              item
              md={3}
              xs={3}
            >
              {colHeader('Item', 'left')}
            </Grid>
            <Grid
              item
              md={2}
              xs={2}
            >
              {colHeader('Qty')}
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {colHeader('Unit Price')}
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {colHeader('Discount')}
            </Grid>
            <Grid
              item
              md={3}
              xs={3}
            >
              {colHeader('Amount')}
            </Grid>
          </Grid>
        </Box>

        {/* Basket items — scrollable */}
        <Box
          sx={{
            flex: 1,
            overflowY: 'auto',
            backgroundColor: appColors.white,
            scrollbarWidth: 'thin',
            '&::-webkit-scrollbar': { width: '3px' },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: '#94a3b8',
              borderRadius: '2px',
            },
          }}
        >
          <BasketItems />
        </Box>

        {/* Summary footer */}
        <Summary />

        {/* Tablet checkout button */}
        {isTablet && (
          <Box sx={{ px: 1.5, pb: 1.5, pt: 1, backgroundColor: appColors.white }}>
            <Button
              disabled={!hasItems}
              fullWidth
              onClick={() => setOpenPayment(true)}
              startIcon={<PointOfSaleIcon sx={{ fontSize: '1.4rem !important' }} />}
              sx={{
                py: 1.5,
                borderRadius: '10px',
                fontSize: '1rem',
                fontWeight: 800,
                letterSpacing: '0.5px',
                textTransform: 'none',
                background: hasItems
                  ? 'linear-gradient(135deg, #0F8B8D 0%, #0F1D4D 100%)'
                  : undefined,
                boxShadow: hasItems ? '0 4px 16px rgba(15,139,141,0.38)' : undefined,
                color: hasItems ? appColors.white : undefined,
                '&:hover': {
                  background: hasItems
                    ? 'linear-gradient(135deg, #0d7a7c 0%, #0a1640 100%)'
                    : undefined,
                  boxShadow: hasItems ? '0 6px 22px rgba(15,139,141,0.52)' : undefined,
                },
                '&.Mui-disabled': {
                  background: 'rgba(148,163,184,0.2)',
                  color: 'rgba(0,0,0,0.3)',
                },
              }}
              variant="contained"
            >
              Checkout
            </Button>
          </Box>
        )}
      </Box>

      {/* Payment dialog — rendered outside the sliding panel so it's not clipped */}
      {isTablet && (
        <PaymentMethodsModel
          handleClose={() => setOpenPayment(false)}
          open={openPayment}
          paymentType={PaymentType.CACHE}
        />
      )}
    </>
  );
};

export default React.memo(Index);
