import * as React from 'react';
import Box from '@mui/material/Box';
import CssBaseline from '@mui/material/CssBaseline';
import { ListItemButton, ListItemText, Tooltip } from '@mui/material';
import { alpha } from '@mui/material/styles';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { useDrawerState } from './hooks/useDrawerState';
import { StyledAppBar, StyledDrawer, DrawerHeader } from './styles';
import { NAVY } from './constants';
import AppBarToolbar from './components/AppBarToolbar';
import DrawerLogoBar from './components/DrawerLogoBar';
import DrawerMenuList from './components/DrawerMenuList';
import HelpSupportModal from './components/HelpSupportModal';

export default function MiniDrawer({ children }:
  { children: React.ReactNode }) {
  const [helpOpen, setHelpOpen] = React.useState(false);
  const {
    isSmall,
    open,
    setOpen,
    userHasRight,
    navigate,
    currentMenuName,
    expandMenu,
    profile,
    handleProfileClick,
    handleProfileClose,
    userName,
    companyName,
    branchName,
    noticeText,
    hasNotice,
    userImageUrl,
    isFullPage,
    hideDrawer,
    handleDrawerOpen,
    handleDrawerClose,
    handleMainMenuItemClick,
  } = useDrawerState();

  return (
    <Box sx={{ display: 'flex', overflowX: 'hidden', width: '100%' }}>
      <CssBaseline />

      <StyledAppBar
        fullView={isFullPage}
        open={!isSmall && open}
        position="fixed"
      >
        <AppBarToolbar
          branchName={branchName}
          companyName={companyName}
          hasNotice={hasNotice}
          isFullPage={isFullPage}
          isSmall={isSmall}
          noticeText={noticeText}
          onDrawerOpen={handleDrawerOpen}
          onProfileClick={handleProfileClick}
          onProfileClose={handleProfileClose}
          open={open}
          profile={profile}
          userImageUrl={userImageUrl}
          userName={userName}
        />
      </StyledAppBar>

      {!hideDrawer && (
        <StyledDrawer
          onClose={() => setOpen(false)}
          open={open}
          sx={{
            '& .MuiDrawer-paper': { display: 'flex', flexDirection: 'column' },
            ...(isSmall ? { zIndex: (theme) => theme.zIndex.drawer + 3 } : {}),
          }}
          variant={isSmall ? 'temporary' : 'permanent'}
        >
          <DrawerLogoBar
            companyName={companyName}
            onClose={handleDrawerClose}
            open={open}
          />

          {/* Scrollable menu area */}
          <Box sx={{ flex: 1, overflowX: 'hidden', overflowY: 'auto' }}>
            <DrawerMenuList
              currentMenuName={currentMenuName}
              expandMenu={expandMenu}
              isSmall={isSmall}
              navigate={navigate}
              onMainItemClick={handleMainMenuItemClick}
              open={open}
              setOpen={setOpen}
              userHasRight={userHasRight}
            />
          </Box>

          {/* Help & Support — pinned at bottom */}
          <Box
            sx={{
              borderTop: `1px solid ${alpha('#fff', 0.07)}`,
              p: '8px',
            }}
          >
            <Tooltip arrow placement="right-start" title={!open ? 'Help & Support' : ''}>
              <ListItemButton
                onClick={() => setHelpOpen(true)}
                sx={{
                  alignItems: 'center',
                  borderRadius: 1.5,
                  display: 'flex',
                  gap: open ? 1.25 : 0,
                  justifyContent: open ? 'flex-start' : 'center',
                  minHeight: 40,
                  px: open ? 1.25 : 0,
                  py: 0.4,
                  '&:hover': { background: alpha('#fff', 0.06) },
                }}
              >
                <Box
                  sx={{
                    alignItems: 'center',
                    background: alpha('#fff', 0.1),
                    borderRadius: '6px',
                    color: alpha('#fff', 0.55),
                    display: 'flex',
                    flexShrink: 0,
                    height: 26,
                    justifyContent: 'center',
                    width: 26,
                  }}
                >
                  <HelpOutlineIcon sx={{ fontSize: 18 }} />
                </Box>

                {open && (
                  <ListItemText
                    primary="Help & Support"
                    primaryTypographyProps={{
                      color: alpha('#fff', 0.65),
                      fontSize: '13px',
                      fontWeight: 500,
                    }}
                  />
                )}
              </ListItemButton>
            </Tooltip>
          </Box>
        </StyledDrawer>
      )}

      <Box
        component="main"
        sx={{
          background: '#F4F5F7',
          flexGrow: 1,
          height: '100vh',
          minWidth: 0,
          overflowX: 'hidden',
          overflowY: 'auto',
          p: { xs: 1.5, sm: 2, md: 2, lg: 3 },
        }}
      >
        <DrawerHeader />
        {children}
      </Box>

      <HelpSupportModal onClose={() => setHelpOpen(false)} open={helpOpen} />
    </Box>
  );
}
