import { Box, CircularProgress, Grid, InputAdornment, TextField } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import SearchIcon from '@mui/icons-material/Search';
import {
  useGetUserQuery,
  useLazySearchCustomerByMobileQuery,
} from '../../../posApi';
import CustomerProfile from './CustomerProfile';
import NewCustomer from '../../../Customer/component/NewCustomer';
import SearchProduct from './SearchProduct';
import { useAppDispatch } from '../../../../store/hooks';
import { addCustomerDetailes } from '../../store/SalesRichBasketSlice';
import { useSelector } from 'react-redux';
import { selectBasket } from '../../store/SalesRichBasketSelector';
import { ICustomerData } from '../../../../core/Interface/customer.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

const Customer = () => {
  const [mobileNumber, setMobileNumber] = useState<string>('');
  const [openPopup, setOpenPopup] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [prevMobileNumber, setPrevMobileNumber] = useState<string>('');
  const inputRef = useRef<HTMLInputElement>(null);
  const dispatch = useAppDispatch();
  const basket = useSelector(selectBasket);

  const [triggerSearch, { data, isLoading, isFetching }] =
    useLazySearchCustomerByMobileQuery();

  const isSearching = isLoading || isFetching;

  const customerDataMemo = useMemo(() => {
    return (data?.data as ICustomerData[]) ?? [];
  }, [data?.data]);

  const safeTriggerSearch = (mobile: string, refresh = false) => {
    if (!mobile) return;
    if (!refresh && mobile === prevMobileNumber) return;

    setPrevMobileNumber(mobile);
    triggerSearch(mobile);
    setHasSearched(true);
  };
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (
      event.key === 'Enter' &&
      (mobileNumber.length === 10 || mobileNumber.length === 9)
    ) {
      safeTriggerSearch(mobileNumber, true);
    }
  };

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    if (value.length <= 10 && /^\d*$/.test(value)) {
      setMobileNumber(value);
    }
  };

  useEffect(() => {
    if (
      hasSearched &&
      !isLoading &&
      !isFetching &&
      customerDataMemo.length === 0
    ) {
      setOpenPopup(true);
    }
  }, [isLoading, isFetching, customerDataMemo, hasSearched]);

  useEffect(() => {
    if (customerDataMemo.length > 0) {
      const customer = customerDataMemo[0];

      dispatch(
        addCustomerDetailes({
          id: customer.id,
          mobile: customer.mobile,
          customerName: customer.name,
        })
      );
    }
  }, [customerDataMemo, dispatch]);

  useEffect(() => {
    if (basket.mobile) {
      setMobileNumber(basket.mobile);
      setPrevMobileNumber(basket.mobile);
      setHasSearched(false);
      setOpenPopup(false);

      if (basket.mobile.length === 9 || basket.mobile.length === 10) {
        safeTriggerSearch(basket.mobile);
      }
    } else {
      setMobileNumber('');
      setPrevMobileNumber('');
      setHasSearched(false);
      setOpenPopup(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [basket.mobile, basket.customerId]);

  const { data: companyData } = useGetUserQuery();

  const isImageEnabled = useMemo(() => {
    if (
      companyData?.data &&
      typeof companyData.data === 'object' &&
      'company' in companyData.data
    ) {
      return (
        (companyData.data as { company: { isImageEnabled: boolean } }).company
          .isImageEnabled ?? false
      );
    }
    return false;
  }, [companyData]);

  return (
    <Box>
      <Grid
        container
        spacing={1}
        sx={{ fontWeight: 800, pb: 2 }}
      >
        <Grid
          item
          md={6}
        >
          <TextField
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  {isSearching ? (
                    <CircularProgress size={16} sx={{ color: TEAL }} />
                  ) : (
                    <SearchIcon
                      onClick={() => {
                        if (
                          mobileNumber.length === 10 ||
                          mobileNumber.length === 9
                        ) {
                          safeTriggerSearch(mobileNumber, true);
                        }
                      }}
                      sx={{
                        color: (mobileNumber.length === 9 || mobileNumber.length === 10)
                          ? TEAL
                          : alpha(NAVY, 0.3),
                        cursor: (mobileNumber.length === 9 || mobileNumber.length === 10)
                          ? 'pointer'
                          : 'default',
                        fontSize: 17,
                        transition: 'color 0.15s',
                      }}
                    />
                  )}
                </InputAdornment>
              ),
            }}
            autoComplete="off"
            autoFocus
            disabled={isSearching}
            fullWidth
            inputProps={{ maxLength: 10 }}
            inputRef={inputRef}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder="Mobile number…"
            size="small"
            sx={{
              '& .MuiOutlinedInput-input': { fontSize: 13 },
              '& .MuiOutlinedInput-root': {
                backgroundColor: '#fff',
                borderRadius: '10px',
                transition: 'box-shadow 0.2s',
                '& fieldset': {
                  borderColor: isSearching ? TEAL : alpha(NAVY, 0.18),
                  borderWidth: isSearching ? '1.5px' : '1px',
                  transition: 'border-color 0.2s',
                },
                '&.Mui-focused fieldset': {
                  borderColor: TEAL,
                  borderWidth: '1.5px',
                },
                '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                '&.Mui-disabled': {
                  backgroundColor: alpha(TEAL, 0.03),
                },
                '&.Mui-disabled fieldset': {
                  borderColor: alpha(TEAL, 0.35),
                  borderWidth: '1.5px',
                },
              },
            }}
            value={mobileNumber}
            variant="outlined"
          />
        </Grid>

        <Grid
          item
          md={6}
        >
          <SearchProduct />
        </Grid>
      </Grid>

      {basket.mobile && (
        <CustomerProfile
          customerData={customerDataMemo[0]}
          isLoading={isSearching}
        />
      )}
      {openPopup && (
        <NewCustomer
          data={{ mobile: mobileNumber }}
          handleCloseDialog={() => setOpenPopup(false)}
          isImageEnabled={isImageEnabled}
          onSuccess={(mobile) => {
            setMobileNumber(mobile);
            setPrevMobileNumber(mobile);
            triggerSearch(mobile);
          }}
          openModel={openPopup}
          title={`Add Customer`}
        />
      )}
    </Box>
  );
};

export default React.memo(Customer);
