/* eslint-disable jsx-a11y/alt-text */
import {
  Box,
  Button,
  CircularProgress,
  Divider,
  Fade,
  InputAdornment,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import NewUserDialog from './NewUserDialog';
import { useFormik } from 'formik';
import { useAppDispatch } from '../../store/hooks';
import { setEnableAuth } from './AuthSlice';
import { useLoginMutation } from '../posApi';
import { useNotifier } from '../../core/Notifier';
import { IAuth } from '../../core/Interface/api.interface';
import { appColors } from '../../theme/appColors';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import VisibilityOutlinedIcon from '@mui/icons-material/VisibilityOutlined';
import VisibilityOffOutlinedIcon from '@mui/icons-material/VisibilityOffOutlined';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';

const FIELD_SX = {
  width: '100%',
  '& .MuiOutlinedInput-root': {
    borderRadius: '12px',
    backgroundColor: '#F8F9FF',
    transition: 'all 0.25s ease',
    '& fieldset': { borderColor: appColors.black[20], borderWidth: '1.5px' },
    '&:hover fieldset': { borderColor: appColors.reflexBlue[60] },
    '&.Mui-focused': {
      backgroundColor: appColors.white,
      boxShadow: `0 0 0 3px ${appColors.reflexBlue[20]}`,
      '& fieldset': { borderColor: appColors.reflexBlue[100], borderWidth: '2px' },
    },
  },
  '& .MuiInputBase-input': {
    padding: '13px 14px 13px 0',
    fontSize: '0.9375rem',
    color: appColors.black[80],
    '&::placeholder': { color: appColors.black[30], opacity: 1 },
  },
};

const Login = () => {
  const dispatch = useAppDispatch();
  const { showErrorMessage } = useNotifier();
  const [login, { isLoading }] = useLoginMutation();
  const [showPassword, setShowPassword] = useState(false);
  const [newUserOpen, setNewUserOpen] = useState(false);

  const formik = useFormik({
    initialValues: { username: '', password: '' },
    onSubmit: async (values) => {
      try {
        const loginResponse = await login(values).unwrap();
        if (!loginResponse.status) {
          showErrorMessage(loginResponse.message);
        } else {
          const tokenData = loginResponse.data as IAuth;
          localStorage.setItem('token', tokenData.token);
          dispatch(setEnableAuth());
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(
    () => formik.values.username !== '' && formik.values.password !== '',
    [formik.values]
  );

  const fillDemo = () => {
    formik.setFieldValue('username', 'demo_admin');
    formik.setFieldValue('password', 'Demo@1234');
  };

  return (
    <Fade in timeout={700}>
      <Box sx={{ width: '100%', maxWidth: 420, position: 'relative', zIndex: 1 }}>

        {/* Card */}
        <Box
          sx={{
            backgroundColor: appColors.white,
            colorScheme: 'light',
            borderRadius: '20px',
            boxShadow: '0 4px 6px rgba(0,20,137,0.04), 0 12px 40px rgba(0,20,137,0.12), 0 2px 8px rgba(0,20,137,0.06)',
            overflow: 'hidden',
          }}
        >
          {/* Top accent bar */}
          <Box
            sx={{
              height: 4,
              background: `linear-gradient(90deg, ${appColors.reflexBlue[100]} 0%, #4F6AF5 60%, #7B93FF 100%)`,
            }}
          />

          <Box sx={{ p: { xs: 3, sm: '36px 40px 40px' } }}>

            {/* Header */}
            <Box sx={{ mb: 3.5, textAlign: 'center' }}>
              <Box
                sx={{
                  width: 56,
                  height: 56,
                  borderRadius: '16px',
                  background: `linear-gradient(135deg, ${appColors.reflexBlue[100]} 0%, #3352CC 100%)`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  mx: 'auto',
                  mb: 2.5,
                  boxShadow: '0 8px 24px rgba(15,29,77,0.28)',
                }}
              >
                <LockOutlinedIcon sx={{ color: '#fff', fontSize: 26 }} />
              </Box>

              <Typography
                sx={{
                  fontSize: { xs: '1.5rem', md: '1.7rem' },
                  fontWeight: 800,
                  color: appColors.reflexBlue[100],
                  letterSpacing: '-0.02em',
                  mb: 0.6,
                }}
              >
                Welcome back
              </Typography>
              <Typography sx={{ fontSize: '0.875rem', color: appColors.black[40], lineHeight: 1.5 }}>
                Sign in to your Alles POS account
              </Typography>
            </Box>

            {/* Form */}
            <Box component="form" noValidate onSubmit={formik.handleSubmit}>
              <Stack spacing={2.5}>

                {/* Username */}
                <Box>
                  <Typography
                    component="label"
                    sx={{
                      display: 'block',
                      fontSize: '0.8125rem',
                      fontWeight: 600,
                      color: appColors.black[70],
                      mb: 0.75,
                    }}
                  >
                    Username
                  </Typography>
                  <TextField
                    autoComplete="username"
                    fullWidth
                    placeholder="Enter your username"
                    {...formik.getFieldProps('username')}
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <PersonOutlineIcon sx={{ color: appColors.reflexBlue[60], fontSize: '1.2rem' }} />
                        </InputAdornment>
                      ),
                    }}
                    sx={FIELD_SX}
                  />
                </Box>

                {/* Password */}
                <Box>
                  <Typography
                    component="label"
                    sx={{
                      display: 'block',
                      fontSize: '0.8125rem',
                      fontWeight: 600,
                      color: appColors.black[70],
                      mb: 0.75,
                    }}
                  >
                    Password
                  </Typography>
                  <TextField
                    autoComplete="current-password"
                    fullWidth
                    placeholder="Enter your password"
                    type={showPassword ? 'text' : 'password'}
                    {...formik.getFieldProps('password')}
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <LockOutlinedIcon sx={{ color: appColors.reflexBlue[60], fontSize: '1.2rem' }} />
                        </InputAdornment>
                      ),
                      endAdornment: (
                        <InputAdornment position="end">
                          <Box
                            onClick={() => setShowPassword((p) => !p)}
                            sx={{
                              cursor: 'pointer',
                              display: 'flex',
                              color: appColors.black[40],
                              '&:hover': { color: appColors.reflexBlue[80] },
                            }}
                          >
                            {showPassword
                              ? <VisibilityOffOutlinedIcon sx={{ fontSize: '1.2rem' }} />
                              : <VisibilityOutlinedIcon sx={{ fontSize: '1.2rem' }} />}
                          </Box>
                        </InputAdornment>
                      ),
                    }}
                    sx={FIELD_SX}
                  />
                </Box>

                {/* Sign In */}
                <Button
                  autoFocus
                  disableElevation
                  disabled={!formValid || isLoading}
                  endIcon={!isLoading && formValid ? <ArrowForwardIcon sx={{ fontSize: '1.1rem !important' }} /> : undefined}
                  fullWidth
                  sx={{
                    mt: 0.5,
                    py: '14px',
                    borderRadius: '12px',
                    fontSize: '0.9375rem',
                    fontWeight: 700,
                    textTransform: 'none',
                    letterSpacing: '0.3px',
                    background: `linear-gradient(135deg, ${appColors.reflexBlue[100]} 0%, #3352CC 100%)`,
                    boxShadow: `0 4px 16px rgba(15,29,77,0.30)`,
                    transition: 'all 0.25s ease',
                    '&:hover': {
                      background: `linear-gradient(135deg, #1a2f6b 0%, #2540AA 100%)`,
                      boxShadow: `0 8px 28px rgba(15,29,77,0.40)`,
                      transform: 'translateY(-1px)',
                    },
                    '&:active': { transform: 'translateY(0)' },
                    '&.Mui-disabled': {
                      background: appColors.black[10],
                      color: appColors.black[30],
                      boxShadow: 'none',
                    },
                  }}
                  type="submit"
                  variant="contained"
                >
                  {isLoading ? (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <CircularProgress size={18} sx={{ color: appColors.white }} />
                      <span>Signing in…</span>
                    </Box>
                  ) : 'Sign In'}
                </Button>

                {/* OR divider */}
                <Divider sx={{ '&::before, &::after': { borderColor: appColors.black[10] } }}>
                  <Typography sx={{ fontSize: '0.75rem', color: appColors.black[30], px: 1, fontWeight: 500 }}>
                    or
                  </Typography>
                </Divider>

                {/* New User */}
                <Button
                  disableElevation
                  fullWidth
                  onClick={() => setNewUserOpen(true)}
                  sx={{
                    borderRadius: '12px',
                    textTransform: 'none',
                    fontSize: '0.9rem',
                    fontWeight: 600,
                    py: '12px',
                    color: appColors.reflexBlue[80],
                    border: `1.5px solid ${appColors.reflexBlue[20]}`,
                    backgroundColor: '#F3F6FF',
                    transition: 'all 0.2s ease',
                    '&:hover': {
                      backgroundColor: '#E8EEFF',
                      borderColor: appColors.reflexBlue[60],
                      transform: 'translateY(-1px)',
                      boxShadow: `0 4px 12px rgba(15,29,77,0.10)`,
                    },
                  }}
                  variant="outlined"
                >
                  New User? Explore Demo
                </Button>

              </Stack>
            </Box>

            {/* Security note */}
            <Box sx={{ mt: 3, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.75 }}>
              <LockOutlinedIcon sx={{ fontSize: '0.72rem', color: appColors.black[30] }} />
              <Typography sx={{ fontSize: '0.7rem', color: appColors.black[30], letterSpacing: '0.02em' }}>
                Secured with 256-bit SSL encryption
              </Typography>
            </Box>

          </Box>
        </Box>

        {/* Footer */}
        <Typography sx={{ textAlign: 'center', mt: 2.5, fontSize: '0.72rem', fontWeight: 500, color: appColors.black[60] }}>
          © {new Date().getFullYear()} Alles POS · All rights reserved
        </Typography>

        <NewUserDialog
          onClose={() => setNewUserOpen(false)}
          onFillDemo={fillDemo}
          open={newUserOpen}
        />

      </Box>
    </Fade>
  );
};

export default React.memo(Login);
