import React, { useState } from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogContent,
  Divider,
  IconButton,
  Stack,
  Tooltip,
  Typography,
} from '@mui/material';
import CloseOutlinedIcon from '@mui/icons-material/CloseOutlined';
import ContentCopyOutlinedIcon from '@mui/icons-material/ContentCopyOutlined';
import CheckOutlinedIcon from '@mui/icons-material/CheckOutlined';
import PersonOutlineOutlinedIcon from '@mui/icons-material/PersonOutlineOutlined';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import LinkOutlinedIcon from '@mui/icons-material/LinkOutlined';
import PhoneIphoneOutlinedIcon from '@mui/icons-material/PhoneIphoneOutlined';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import LocalPhoneOutlinedIcon from '@mui/icons-material/LocalPhoneOutlined';
import EmailOutlinedIcon from '@mui/icons-material/EmailOutlined';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import PointOfSaleOutlinedIcon from '@mui/icons-material/PointOfSaleOutlined';
import InventoryOutlinedIcon from '@mui/icons-material/InventoryOutlined';
import BarChartOutlinedIcon from '@mui/icons-material/BarChartOutlined';
import { appColors } from '../../theme/appColors';

const DEMO_URL = 'https://demo.allespos.com';

const DEMO_CREDS = [
  { icon: <PersonOutlineOutlinedIcon sx={{ fontSize: '1rem' }} />, label: 'Username', value: 'demo_admin' },
  { icon: <LockOutlinedIcon sx={{ fontSize: '1rem' }} />, label: 'Password', value: 'Demo@1234' },
];

const CONTACTS = [
  { icon: <PhoneIphoneOutlinedIcon sx={{ fontSize: '1rem' }} />, label: 'Mobile', value: '+61 406 690 485 / +94 77 735 5075', href: 'tel:+61406690485' },
  { icon: <WhatsAppIcon sx={{ fontSize: '1rem' }} />, label: 'WhatsApp', value: '+61 406 690 485 / +94 77 735 5075', href: 'https://wa.me/61406690485', color: '#25D366' },
  { icon: <LocalPhoneOutlinedIcon sx={{ fontSize: '1rem' }} />, label: 'Local', value: '+61 406 690 485 / +94 77 735 5075', href: 'tel:+61406690485' },
  { icon: <EmailOutlinedIcon sx={{ fontSize: '1rem' }} />, label: 'Email', value: 'support@allespos.com', href: 'mailto:support@allespos.com' },
];

const FEATURES = [
  { icon: <PointOfSaleOutlinedIcon sx={{ fontSize: '1.1rem' }} />, label: 'Sales & Checkout', desc: 'Fast POS billing with multiple payment modes' },
  { icon: <StorefrontOutlinedIcon sx={{ fontSize: '1.1rem' }} />, label: 'Multi-outlet', desc: 'Manage multiple branches from one dashboard' },
  { icon: <InventoryOutlinedIcon sx={{ fontSize: '1.1rem' }} />, label: 'Inventory', desc: 'Real-time stock tracking and low-stock alerts' },
  { icon: <BarChartOutlinedIcon sx={{ fontSize: '1.1rem' }} />, label: 'Analytics', desc: 'Sales reports, profit trends and insights' },
];

interface CopyButtonProps { value: string }
const CopyButton = ({ value }: CopyButtonProps) => {
  const [copied, setCopied] = useState(false);
  const handle = () => {
    navigator.clipboard?.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };
  return (
    <Tooltip placement="top" title={copied ? 'Copied!' : 'Copy'}>
      <IconButton onClick={handle} size="small" sx={{ color: copied ? '#25D366' : appColors.black[30], '&:hover': { color: appColors.reflexBlue[80] } }}>
        {copied
          ? <CheckOutlinedIcon sx={{ fontSize: '0.85rem' }} />
          : <ContentCopyOutlinedIcon sx={{ fontSize: '0.85rem' }} />}
      </IconButton>
    </Tooltip>
  );
};

interface Props {
  onFillDemo: () => void;
  open: boolean;
  onClose: () => void;
}

const NewUserDialog = ({ open, onClose, onFillDemo }: Props) => {
  const handleFill = () => { onFillDemo(); onClose(); };

  return (
    <Dialog
      fullWidth
      maxWidth="sm"
      onClose={onClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '20px',
          overflow: 'hidden',
          boxShadow: '0 24px 64px rgba(0,20,137,0.18)',
        },
      }}
    >
      {/* Header */}
      <Box
        sx={{
          background: `linear-gradient(135deg, ${appColors.reflexBlue[100]} 0%, ${appColors.royalBlue[80]} 100%)`,
          px: 3,
          pt: 3,
          pb: 2.5,
          position: 'relative',
        }}
      >
        <IconButton
          onClick={onClose}
          size="small"
          sx={{ position: 'absolute', top: 12, right: 12, color: 'rgba(255,255,255,0.7)', '&:hover': { color: '#fff', backgroundColor: 'rgba(255,255,255,0.12)' } }}
        >
          <CloseOutlinedIcon fontSize="small" />
        </IconButton>

        <Chip
          label="New to Alles POS?"
          size="small"
          sx={{ backgroundColor: 'rgba(255,255,255,0.15)', color: '#fff', fontSize: '0.7rem', fontWeight: 600, mb: 1.5, border: '1px solid rgba(255,255,255,0.25)' }}
        />
        <Typography sx={{ fontSize: '1.35rem', fontWeight: 800, color: '#fff', lineHeight: 1.2, mb: 0.5 }}>
          Explore the Demo
        </Typography>
        <Typography sx={{ fontSize: '0.85rem', color: 'rgba(255,255,255,0.65)' }}>
          Try everything risk-free — no setup required.
        </Typography>
      </Box>

      <DialogContent sx={{ p: 3 }}>
        <Stack spacing={3}>

          {/* Demo URL */}
          <Box>
            <Typography sx={{ fontSize: '0.7rem', fontWeight: 700, color: appColors.black[40], textTransform: 'uppercase', letterSpacing: '0.08em', mb: 1.25 }}>
              Demo URL
            </Typography>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                gap: 1.5,
                px: 2,
                py: 1.5,
                borderRadius: '12px',
                backgroundColor: '#F3F6FF',
                border: `1.5px solid ${appColors.reflexBlue[20]}`,
              }}
            >
              <LinkOutlinedIcon sx={{ color: appColors.reflexBlue[60], fontSize: '1rem' }} />
              <Typography
                component="a"
                href={DEMO_URL}
                rel="noopener noreferrer"
                sx={{ flex: 1, fontSize: '0.875rem', fontWeight: 600, color: appColors.reflexBlue[80], textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                target="_blank"
              >
                {DEMO_URL}
              </Typography>
              <CopyButton value={DEMO_URL} />
            </Box>
          </Box>

          {/* Demo credentials */}
          <Box>
            <Typography sx={{ fontSize: '0.7rem', fontWeight: 700, color: appColors.black[40], textTransform: 'uppercase', letterSpacing: '0.08em', mb: 1.25 }}>
              Demo Credentials
            </Typography>
            <Box sx={{ borderRadius: '12px', border: `1.5px dashed ${appColors.reflexBlue[20]}`, backgroundColor: '#F3F6FF', overflow: 'hidden' }}>
              {DEMO_CREDS.map(({ icon, label, value }, i) => (
                <Box key={label}>
                  {i > 0 && <Divider sx={{ borderColor: appColors.reflexBlue[20] }} />}
                  <Box sx={{ display: 'flex', alignItems: 'center', px: 2, py: 1.25, gap: 1.5 }}>
                    <Box sx={{ color: appColors.reflexBlue[60], display: 'flex' }}>{icon}</Box>
                    <Typography sx={{ fontSize: '0.8rem', color: appColors.black[50], minWidth: 72 }}>{label}</Typography>
                    <Typography sx={{ fontSize: '0.875rem', fontWeight: 700, color: appColors.black[80], fontFamily: 'monospace', flex: 1 }}>{value}</Typography>
                    <CopyButton value={value} />
                  </Box>
                </Box>
              ))}
            </Box>
          </Box>

          {/* What's included */}
          <Box>
            <Typography sx={{ fontSize: '0.7rem', fontWeight: 700, color: appColors.black[40], textTransform: 'uppercase', letterSpacing: '0.08em', mb: 1.25 }}>
              What's Included in Demo
            </Typography>
            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.25 }}>
              {FEATURES.map(({ icon, label, desc }) => (
                <Box
                  key={label}
                  sx={{ p: 1.5, borderRadius: '10px', backgroundColor: appColors.black[10], border: `1px solid ${appColors.black[20]}` }}
                >
                  <Box sx={{ color: appColors.reflexBlue[80], display: 'flex', mb: 0.75 }}>{icon}</Box>
                  <Typography sx={{ fontSize: '0.8rem', fontWeight: 700, color: appColors.black[80], mb: 0.25 }}>{label}</Typography>
                  <Typography sx={{ fontSize: '0.72rem', color: appColors.black[50], lineHeight: 1.45 }}>{desc}</Typography>
                </Box>
              ))}
            </Box>
          </Box>

          {/* Contact */}
          <Box>
            <Typography sx={{ fontSize: '0.7rem', fontWeight: 700, color: appColors.black[40], textTransform: 'uppercase', letterSpacing: '0.08em', mb: 1.25 }}>
              Contact Us
            </Typography>
            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 0.5 }}>
              {CONTACTS.map(({ icon, label, value, href, color }) => (
                <Box
                  component="a"
                  href={href}
                  key={label}
                  rel="noopener noreferrer"
                  sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 1.25, py: 1, borderRadius: '8px', textDecoration: 'none', '&:hover': { backgroundColor: appColors.black[10] } }}
                  target="_blank"
                >
                  <Box sx={{ color: color ?? appColors.reflexBlue[60], display: 'flex' }}>{icon}</Box>
                  <Box>
                    <Typography sx={{ fontSize: '0.7rem', color: appColors.black[40], lineHeight: 1.2 }}>{label}</Typography>
                    <Typography sx={{ fontSize: '0.78rem', fontWeight: 600, color: appColors.black[70] }}>{value}</Typography>
                  </Box>
                </Box>
              ))}
            </Box>
          </Box>

        </Stack>
      </DialogContent>

      {/* Actions */}
      <Box sx={{ px: 3, pb: 3, pt: 1, display: 'flex', gap: 1.5 }}>
        <Button
          disableElevation
          fullWidth
          onClick={onClose}
          sx={{ borderRadius: '10px', textTransform: 'none', fontWeight: 600, fontSize: '0.875rem', color: appColors.black[60], border: `1.5px solid ${appColors.black[20]}` }}
          variant="outlined"
        >
          Close
        </Button>
        <Button
          disableElevation
          fullWidth
          onClick={handleFill}
          sx={{
            borderRadius: '10px',
            textTransform: 'none',
            fontWeight: 700,
            fontSize: '0.875rem',
            background: `linear-gradient(135deg, ${appColors.reflexBlue[100]} 0%, ${appColors.royalBlue[80]} 100%)`,
            '&:hover': { background: `linear-gradient(135deg, ${appColors.reflexBlue[90]} 0%, ${appColors.royalBlue[100]} 100%)` },
          }}
          variant="contained"
        >
          Try Demo Now
        </Button>
      </Box>
    </Dialog>
  );
};

export default NewUserDialog;
