import React from 'react';
import Box from '@mui/material/Box';
import Login from './Login';
import { Fade, Typography } from '@mui/material';
import { appColors } from '../../theme/appColors';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import PointOfSaleOutlinedIcon from '@mui/icons-material/PointOfSaleOutlined';
import InventoryOutlinedIcon from '@mui/icons-material/InventoryOutlined';
import BarChartOutlinedIcon from '@mui/icons-material/BarChartOutlined';

const STATS = [
  { value: '500+', label: 'Outlets' },
  { value: '10K+', label: 'Daily Orders' },
  { value: '99.9%', label: 'Uptime' },
];

const FEATURES = [
  { icon: <PointOfSaleOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Sales & Checkout', desc: 'Fast POS billing with multiple payment modes' },
  { icon: <StorefrontOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Multi-outlet', desc: 'Manage multiple branches from one dashboard' },
  { icon: <InventoryOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Inventory', desc: 'Real-time stock tracking and low-stock alerts' },
  { icon: <BarChartOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Analytics', desc: 'Sales reports, profit trends and insights' },
];


const Auth = () => {
  return (
    <Box
      data-testid="Terms and condition Page"
      sx={{ height: '100vh', display: 'flex', overflow: 'hidden' }}
    >
      {/* ══════════════════ LEFT PANEL (3/5) ══════════════════ */}
      <Box
        sx={{
          display: { xs: 'none', md: 'flex' },
          flex: '0 0 60%',
          flexDirection: 'column',
          position: 'relative',
          overflow: 'hidden',
          /* Background image */
          /* background handled by child layer so we can flip image without flipping text */
        }}
      >
        {/* Background image — flipped horizontally */}
        <Box
          sx={{
            position: 'absolute',
            inset: 0,
            backgroundImage: 'url(/images/posBack.jpg)',
            backgroundSize: 'cover',
            // backgroundPosition: 'left 0px top 0px',
            backgroundRepeat: 'no-repeat',
            // transform: 'scaleX(-1)',
            pointerEvents: 'none',
          }}
        />
        {/* Dark overlay for readability */}
        <Box
          sx={{
            position: 'absolute',
            inset: 0,
            background: 'linear-gradient(148deg, rgba(6,12,62,0.78) 0%, rgba(13,24,112,0.70) 45%, rgba(4,8,40,0.82) 100%)',
            pointerEvents: 'none',
          }}
        />

        {/* Content column */}
        <Box
          sx={{
            position: 'relative',
            zIndex: 1,
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            px: { md: 5, lg: 7 },
            pt: { md: 4, lg: 5 },
            pb: { md: 3.5, lg: 4.5 },
            gap: { md: 2, lg: 2.5 },
            justifyContent: 'flex-start',
          }}
        >

          {/* ── 1 & 2. Logo (left) + Headline (right) — same row ── */}
          <Fade in timeout={600}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: { md: 2, lg: 3 }, flex: '0 0 auto' }}>

              {/* Logo */}
              <Box
                component="img"
                src="/images/logo.png"
                sx={{ height: { md: 32, lg: 36 }, width: 'auto', filter: 'brightness(0) invert(1)', flexShrink: 0, mt: 0.5 }}
              />

              {/* Headline text — right side */}
              <Box sx={{ flex: 1, minWidth: 0, textAlign: 'right' }}>
                <Typography
                  sx={{
                    fontSize: { md: '1.8rem', lg: '2.3rem', xl: '2.7rem' },
                    fontWeight: 800,
                    color: '#fff',
                    lineHeight: 1.12,
                    letterSpacing: '-0.03em',
                    mb: 1.25,
                  }}
                >
                  Smarter Sales.
                  <br />
                  <Box component="span" sx={{ color: 'rgba(155,185,255,0.95)' }}>
                    Faster Growth.
                  </Box>
                </Typography>
                <Typography
                  sx={{
                    fontSize: { md: '0.78rem', lg: '0.85rem' },
                    color: 'rgba(255,255,255,0.46)',
                    lineHeight: 1.75,
                    width: '50%',
                    ml: 'auto',
                  }}
                >
                  Your all-in-one POS platform — manage sales, inventory and analytics from one powerful dashboard.
                </Typography>
              </Box>

            </Box>
          </Fade>

          {/* Spacer — pushes bottom content down */}
          <Box sx={{ flex: 1 }} />

          {/* ── 5 & 4. Features (left) + Stats (right) — bottom row ── */}
          <Fade in timeout={1000}>
            <Box sx={{ display: 'flex', gap: { md: 1, lg: 1.5 }, flex: '0 0 auto', alignItems: 'stretch' }}>

              {/* Feature tiles — left */}
              <Box
                sx={{
                  flex: 1,
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: { md: 0.75, lg: 1 },
                }}
              >
                {FEATURES.map(({ icon, label, desc }) => (
                  <Box
                    key={label}
                    sx={{
                      px: { md: 1.25, lg: 1.5 },
                      py: { md: 1, lg: 1.25 },
                      borderRadius: '10px',
                      background: 'rgba(255,255,255,0.06)',
                      border: '1px solid rgba(255,255,255,0.09)',
                    }}
                  >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.4 }}>
                      <Box sx={{ color: 'rgba(160,185,255,0.85)', display: 'flex' }}>{icon}</Box>
                      <Typography sx={{ fontSize: '0.78rem', fontWeight: 700, color: 'rgba(255,255,255,0.80)' }}>
                        {label}
                      </Typography>
                    </Box>
                    <Typography sx={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.38)', lineHeight: 1.5, pl: 0.25 }}>
                      {desc}
                    </Typography>
                  </Box>
                ))}
              </Box>

              {/* Stats — right (vertical stack) */}
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75, width: { md: 80, lg: 90 } }}>
                {STATS.map(({ value, label }) => (
                  <Box
                    key={label}
                    sx={{
                      flex: 1,
                      px: 0.75,
                      py: 0.5,
                      borderRadius: '8px',
                      background: 'rgba(255,255,255,0.06)',
                      border: '1px solid rgba(255,255,255,0.10)',
                      textAlign: 'center',
                      display: 'flex',
                      flexDirection: 'column',
                      justifyContent: 'center',
                    }}
                  >
                    <Typography sx={{ fontSize: { md: '0.85rem', lg: '0.95rem' }, fontWeight: 800, color: '#fff', lineHeight: 1 }}>
                      {value}
                    </Typography>
                    <Typography sx={{ fontSize: '0.58rem', color: 'rgba(255,255,255,0.42)', mt: 0.3, fontWeight: 500 }}>
                      {label}
                    </Typography>
                  </Box>
                ))}
              </Box>

            </Box>
          </Fade>


        </Box>
      </Box>

      {/* ══════════════════ RIGHT PANEL (2/5 on desktop, full on tablet/mobile) ══════════════════ */}
      <Box
        sx={{
          /* Full width when left panel is hidden (< md = < 900px) */
          flex: { xs: 1, md: '0 0 40%' },
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          overflow: 'hidden',
          /* Desktop: soft blue-white. Tablet/mobile: dark brand gradient */
          background: {
            xs: `
              radial-gradient(ellipse at 20% 10%, rgba(80,110,255,0.40) 0%, transparent 50%),
              radial-gradient(ellipse at 80% 90%, rgba(8,14,70,0.55) 0%, transparent 48%),
              linear-gradient(148deg, ${appColors.reflexBlue[100]} 0%, #0d1870 50%, #060c3e 100%)
            `,
            md: `
              radial-gradient(ellipse at 75% 8%,  rgba(200,215,255,0.38) 0%, transparent 55%),
              radial-gradient(ellipse at 25% 92%, rgba(180,200,255,0.22) 0%, transparent 52%),
              linear-gradient(168deg, #EEF2FF 0%, #F4F6FF 55%, #FFFFFF 100%)
            `,
          },
          px: { xs: 3, sm: 5, md: 4, lg: 6 },
          py: { xs: 4, md: 0 },
          gap: { xs: 3, md: 0 },
        }}
      >
        {/* Desktop blobs */}
        <Box sx={{ display: { xs: 'none', md: 'block' }, position: 'absolute', top: -90, right: -90, width: 280, height: 280, borderRadius: '50%', background: 'radial-gradient(circle, rgba(180,200,255,0.28) 0%, transparent 70%)', pointerEvents: 'none' }} />
        <Box sx={{ display: { xs: 'none', md: 'block' }, position: 'absolute', bottom: -70, left: -70, width: 240, height: 240, borderRadius: '50%', background: 'radial-gradient(circle, rgba(200,215,255,0.22) 0%, transparent 70%)', pointerEvents: 'none' }} />

        {/* Tablet / mobile branding header (hidden on desktop) */}
        <Box
          sx={{
            display: { xs: 'flex', md: 'none' },
            flexDirection: 'column',
            alignItems: 'center',
            gap: 1,
          }}
        >
          <Box
            component="img"
            src="/images/logo.png"
            sx={{ height: 40, width: 'auto', filter: 'brightness(0) invert(1)', mb: 0.5 }}
          />
          <Typography sx={{ fontSize: { xs: '1.25rem', sm: '1.5rem' }, fontWeight: 800, color: '#fff', letterSpacing: '-0.02em', textAlign: 'center', lineHeight: 1.2 }}>
            Smarter Sales.<br />
            <Box component="span" sx={{ color: 'rgba(160,185,255,0.9)' }}>Faster Growth.</Box>
          </Typography>
          <Typography sx={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.45)', textAlign: 'center', maxWidth: 300 }}>
            Your all-in-one POS platform — manage sales, inventory and analytics.
          </Typography>
        </Box>

        <Login />
      </Box>
    </Box>
  );
};

export default Auth;
