/* eslint-disable jsx-a11y/alt-text */
import React, { useCallback, useEffect, useState } from 'react';
import {
  Avatar,
  Box,
  IconButton,
  Toolbar,
  Tooltip,
  Typography,
} from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import CampaignOutlinedIcon from '@mui/icons-material/CampaignOutlined';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import FullscreenIcon from '@mui/icons-material/Fullscreen';
import FullscreenExitIcon from '@mui/icons-material/FullscreenExit';
import Typewriter from 'typewriter-effect';
import ProfilePopup from '../../../components/ModelPopup/ProfilePopup';
import { TEAL, MID, NAVY } from '../constants';
import NotificationBell from './NotificationBell';

interface AppBarToolbarProps {
  isFullPage: boolean;
  isSmall: boolean;
  open: boolean;
  companyName: string | false;
  hasNotice: boolean;
  noticeText: string | string[];
  userName: string | false;
  branchName: string;
  userImageUrl: string;
  profile: HTMLElement | null;
  onDrawerOpen: () => void;
  onProfileClick: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onProfileClose: () => void;
}

const AppBarToolbar: React.FC<AppBarToolbarProps> = ({
  isFullPage,
  isSmall,
  open,
  companyName,
  hasNotice,
  noticeText,
  userName,
  branchName,
  userImageUrl,
  profile,
  onDrawerOpen,
  onProfileClick,
  onProfileClose,
}) => {
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    const handleChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };
    document.addEventListener('fullscreenchange', handleChange);
    return () => document.removeEventListener('fullscreenchange', handleChange);
  }, []);

  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }, []);

  return (
    <Toolbar
      sx={{
        alignItems: 'center',
        display: 'flex',
        gap: 1,
        minHeight: { xs: 56, sm: 64 },
        px: { xs: 1.5, sm: 2.5 },
      }}
    >
      {/* Hamburger */}
      {!isFullPage && (
        <IconButton
          aria-label="open drawer"
          edge="start"
          onClick={onDrawerOpen}
          sx={{
            borderRadius: '8px',
            color: '#4B5563',
            flexShrink: 0,
            height: 36,
            mr: 0.5,
            width: 36,
            '&:hover': { background: '#F3F4F6' },
            ...(!isSmall && open && { display: 'none' }),
          }}
        >
          <MenuIcon sx={{ fontSize: 20 }} />
        </IconButton>
      )}

      {/* Logo + Company */}
      {!isSmall && (!open || isFullPage) && (
        <Box
          sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 1 }}
        >
          <Box
            sx={{
              alignItems: 'center',
              background: '#fff',
              border: '1px solid rgba(15,29,77,0.1)',
              borderRadius: '8px',
              display: 'flex',
              height: 36,
              justifyContent: 'center',
              overflow: 'hidden',
              width: 48,
            }}
          >
            <img
              height={26}
              src="/images/logo.png"
            />
          </Box>
          <Box>
            <Typography
              sx={{ color: NAVY, fontSize: 13, fontWeight: 800, lineHeight: 1.2 }}
            >
              {companyName || 'POS System'}
            </Typography>
            <Typography sx={{ color: '#9CA3AF', fontSize: 10, fontWeight: 500 }}>
              Management Portal
            </Typography>
          </Box>
        </Box>
      )}

      {/* Divider */}
      {!isSmall && (!open || isFullPage) && (
        <Box
          sx={{
            borderLeft: '1px solid #E5E7EB',
            flexShrink: 0,
            height: 28,
            mx: 0.5,
          }}
        />
      )}

      {/* Typewriter notice */}
      {!isSmall && hasNotice && (
        <Box
          sx={{
            alignItems: 'center',
            display: 'flex',
            flex: 1,
            gap: 1,
            maxWidth: 520,
            minWidth: 0,
            mx: 'auto',
            overflow: 'hidden',
          }}
        >
          <Box
            sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 0.5 }}
          >
            <Box
              sx={{
                '@keyframes livePulse': {
                  '0%, 100%': {
                    boxShadow: `0 0 0 0 ${TEAL}55`,
                    transform: 'scale(1)',
                  },
                  '50%': {
                    boxShadow: `0 0 0 4px ${TEAL}00`,
                    transform: 'scale(1.15)',
                  },
                },
                animation: 'livePulse 1.8s ease-in-out infinite',
                background: TEAL,
                borderRadius: '50%',
                height: 7,
                width: 7,
              }}
            />
            <CampaignOutlinedIcon sx={{ color: TEAL, fontSize: 16 }} />
          </Box>
          <Box
            sx={{
              color: '#374151',
              flex: 1,
              fontSize: 13,
              fontWeight: 500,
              minWidth: 0,
              overflow: 'hidden',
              '& .Typewriter__wrapper': { display: 'inline' },
            }}
          >
            <Typewriter
              options={{
                autoStart: true,
                cursor: '|',
                delay: 55,
                deleteSpeed: 30,
                loop: true,
                strings: noticeText,
              }}
            />
          </Box>
        </Box>
      )}

      {/* Spacer */}
      <Box sx={{ flex: 1 }} />

      {/* Notification bell */}
      {!isSmall && <NotificationBell />}

      {/* Fullscreen toggle */}
      {!isSmall && (
        <Tooltip title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}>
          <IconButton
            onClick={toggleFullscreen}
            sx={{
              borderRadius: '8px',
              color: '#6B7280',
              flexShrink: 0,
              height: 36,
              width: 36,
              '&:hover': { background: '#F3F4F6' },
            }}
          >
            {isFullscreen
              ? <FullscreenExitIcon sx={{ fontSize: 20 }} />
              : <FullscreenIcon sx={{ fontSize: 20 }} />
            }
          </IconButton>
        </Tooltip>
      )}

      {/* User info + avatar */}
      <Box
        sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 0.75 }}
      >
        {!isSmall && (
          <Box sx={{ textAlign: 'right' }}>
            <Typography
              sx={{ color: '#111827', fontSize: 13, fontWeight: 700, lineHeight: 1.2 }}
            >
              {userName}
            </Typography>
            {branchName && (
              <Typography sx={{ color: '#9CA3AF', fontSize: 11, fontWeight: 500 }}>
                {branchName}
              </Typography>
            )}
          </Box>
        )}

        <Tooltip title="Open settings">
          <IconButton
            data-testid="user-content"
            onClick={onProfileClick}
            sx={{
              background: `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`,
              borderRadius: '10px',
              height: 36,
              p: 0,
              width: 36,
              '&:hover': {
                background: `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
              },
            }}
          >
            <Avatar
              alt={userName || 'User'}
              src={userImageUrl}
              sx={{ height: 32, width: 32 }}
            />
          </IconButton>
        </Tooltip>

        {!isSmall && (
          <KeyboardArrowDownIcon
            onClick={(e) =>
              onProfileClick(e as unknown as React.MouseEvent<HTMLButtonElement>)
            }
            sx={{ color: '#9CA3AF', cursor: 'pointer', fontSize: 18 }}
          />
        )}
      </Box>

      <ProfilePopup
        Branchname={branchName}
        Username={userName}
        onClose={onProfileClose}
        open={Boolean(profile)}
        profile={profile}
      />
    </Toolbar>
  );
};

export default AppBarToolbar;
