/* eslint-disable jsx-a11y/alt-text */
import React from 'react';
import { Box, IconButton, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useTheme } from '@mui/material/styles';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import { DrawerHeader } from '../styles';
import { TEAL } from '../constants';

interface DrawerLogoBarProps {
  open: boolean;
  companyName: string | false;
  onClose: () => void;
}

const DrawerLogoBar: React.FC<DrawerLogoBarProps> = ({
  open,
  companyName,
  onClose,
}) => {
  const theme = useTheme();

  return (
    <>
      <DrawerHeader
        sx={{
          borderBottom: `1px solid ${alpha('#fff', 0.07)}`,
          justifyContent: 'space-between',
          px: 1.5,
        }}
      >
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.25 }}>
          <Box
            sx={{
              alignItems: 'center',
              background: '#fff',
              borderRadius: '8px',
              display: 'flex',
              height: 36,
              justifyContent: 'center',
              overflow: 'hidden',
              width: 48,
            }}
          >
            <img height={28} src="/images/logo.png" />
          </Box>

          {open && (
            <Box>
              <Typography
                sx={{
                  color: '#fff',
                  fontSize: 13,
                  fontWeight: 800,
                  letterSpacing: 0.2,
                  lineHeight: 1.2,
                }}
              >
                {companyName || 'POS System'}
              </Typography>
              <Typography
                sx={{ color: TEAL, fontSize: 10, fontWeight: 500, opacity: 0.9 }}
              >
                Management Portal
              </Typography>
            </Box>
          )}
        </Box>

        <IconButton
          onClick={onClose}
          sx={{
            borderRadius: '8px',
            color: alpha('#fff', 0.5),
            height: 30,
            width: 30,
            '&:hover': {
              background: alpha('#fff', 0.08),
              color: '#fff',
            },
          }}
        >
          {theme.direction === 'rtl'
            ? <ChevronRightIcon sx={{ fontSize: 18 }} />
            : <ChevronLeftIcon sx={{ fontSize: 18 }} />}
        </IconButton>
      </DrawerHeader>
    </>
  );
};

export default DrawerLogoBar;
